WITH filtered_accounts AS (SELECT *, LOWER(status) AS status_lower FROM accounts WHERE (balance BETWEEN 44000 AND 57000 AND account_type <> 'SAVINGS') OR status NOT IN ('CLOSED', 'OPEN')), summary AS (SELECT CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 17000 THEN 'mid' ELSE 'low' END AS balance_bucket, MIN(opened_date) AS first_opened_date FROM filtered_accounts GROUP BY CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 17000 THEN 'mid' ELSE 'low' END) SELECT * FROM summary
